// ---------------------------------------------------------------------------
// Scenario 8: helm-release-failure
// ---------------------------------------------------------------------------

describe("Scenario 8: helm-release-failure", () => {
  const dir = getFixturePath("helm-release-failure");

  it("fixture directory exists", () => {
    expect(exists(dir)).toBe(true);
  });

  it("has version.yaml with SupportBundle kind", () => {
    const versionPath = path.join(dir, "version.yaml");
    expect(exists(versionPath)).toBe(true);
    expect(fs.readFileSync(versionPath, "utf8")).toContain("SupportBundle");
  });

  it("has cluster_version.json", () => {
    expect(exists(path.join(dir, "cluster-info", "cluster_version.json"))).toBe(true);
  });

  it("analysis.json contains Helm failure analyzer entries", () => {
    const raw = fs.readFileSync(path.join(dir, "analysis.json"), "utf8");
    const results = parseAnalyzerJson(raw);
    expect(results.some((r) => r.severity === "error")).toBe(true);
    expect(results.some((r) => r.severity === "warn")).toBe(true);
    expect(raw).toContain("Helm release 'storefront'");
    expect(raw).toContain("APP_MODE=invalid_mode");
  });

  it("contains a parseable failed Helm release file", () => {
    const releasePath = path.join(dir, "helm", "releases", "storefront.json");
    expect(exists(releasePath)).toBe(true);
    const raw = fs.readFileSync(releasePath, "utf8");
    const releases = parseHelmReleaseContent(raw);
    expect(releases).toHaveLength(1);
    expect(releases[0]!.name).toBe("storefront");
    expect(releases[0]!.status).toBe("failed");
    expect(releases[0]!.chart).toBe("storefront");
    expect(releases[0]!.chartVersion).toBe("2.3.1");
    expect(releases[0]!.values["env"]).toBeDefined();
  });

  it("contains a CrashLoopBackOff hook pod with Helm hook labels", () => {
    const podPath = path.join(
      dir,
      "cluster-resources",
      "pods",
      "default",
      "storefront-hook-pod.yaml",
    );
    expect(exists(podPath)).toBe(true);
    const raw = fs.readFileSync(podPath, "utf8");
    expect(raw).toContain("storefront-hook-pod");
    expect(raw).toContain("helm.sh/hook: post-install");
    expect(raw).toContain("CrashLoopBackOff");
    expect(raw).toContain("APP_MODE");
    expect(raw).toContain("invalid_mode");
  });

  it("events include Failed and BackOff reasons for the hook pod", () => {
    const eventsPath = path.join(dir, "cluster-resources", "events", "default.json");
    expect(exists(eventsPath)).toBe(true);
    const events = parseEventsJson(fs.readFileSync(eventsPath, "utf8"));
    expect(events.some((e) => e.reason === "Failed")).toBe(true);
    expect(events.some((e) => e.reason === "BackOff")).toBe(true);
    expect(events.some((e) => e.message.includes("storefront"))).toBe(true);
  });

  it("hook pod log contains Helm-related startup errors", async () => {
    const logPath = path.join(
      dir,
      "cluster-resources",
      "pods",
      "logs",
      "default",
      "storefront-hook-pod",
      "hook.log",
    );
    expect(exists(logPath)).toBe(true);
    const raw = fs.readFileSync(logPath, "utf8");
    expect(raw).toContain("Helm post-install hook");
    expect(raw).toContain("storefront");
    expect(raw).toContain("invalid_mode");
    expect(raw).toContain("FAILED");

    const logFile = await parseLogFile(logPath);
    expect(logFile.lines.length).toBeGreaterThan(0);
    expect(logFile.errorCount).toBeGreaterThan(0);
  });

  it("createTestBundle works with helm-release-failure scenario", async () => {
    const tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), "sbi-helm-"));
    const outPath = path.join(tmpDir, "helm-release-failure.tar.gz");
    try {
      const result = await createTestBundle(dir, outPath);
      expect(exists(result)).toBe(true);
      expect(fs.statSync(result).size).toBeGreaterThan(0);
    } finally {
      fs.rmSync(tmpDir, { recursive: true, force: true });
    }
  });
});

import * as fsp from 'fs/promises';
import * as yaml from 'js-yaml';

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

/**
 * Parsed representation of a Helm release found in a support bundle.
 *
 * Helm stores release data as base64-encoded, gzip-compressed protobuf
 * inside Kubernetes Secrets (type `helm.sh/release.v1`).  Many support
 * bundles instead capture a JSON/YAML dump of the release metadata
 * produced by `helm list --output json` or the Troubleshoot `helm`
 * collector.
 *
 * This parser handles the simpler JSON/YAML format.  Full protobuf
 * decoding would require a Helm library and is out of MVP scope.
 */
export interface HelmRelease {
  /** Release name (e.g. "my-app"). */
  name: string;
  /** Namespace the release is installed in. */
  namespace: string;
  /** Current revision number. */
  revision: number;
  /** Release status (e.g. "deployed", "failed", "pending-install"). */
  status: string;
  /** Chart name (e.g. "my-chart"). */
  chart: string;
  /** Chart version (e.g. "1.2.3"). */
  chartVersion: string;
  /** App version from Chart.yaml (e.g. "2.0.0"). */
  appVersion: string;
  /** ISO timestamp of last update/install. */
  updatedAt: string;
  /** Raw values override object (user-supplied values). */
  values: Record<string, unknown>;
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function getString(value: unknown, fallback = ''): string {
  return typeof value === 'string' ? value : fallback;
}

function getNumber(value: unknown, fallback = 0): number {
  if (typeof value === 'number') return value;
  if (typeof value === 'string') {
    const parsed = Number(value);
    return Number.isNaN(parsed) ? fallback : parsed;
  }
  return fallback;
}

/**
 * Attempts to parse a single raw Helm release object into a typed
 * {@link HelmRelease}.  Returns `null` when the input is not a valid
 * release record (missing `name` or unrecognisable shape).
 */
function parseRawRelease(raw: unknown): HelmRelease | null {
  if (!isRecord(raw)) return null;

  const name = getString(raw['name']);
  if (name.length === 0) return null;

  // Chart field may be "chart-1.2.3" (Helm list format) or a nested object
  let chart = '';
  let chartVersion = '';
  if (typeof raw['chart'] === 'string') {
    const parts = raw['chart'].match(/^(.+)-(\d+\.\d+.*)$/);
    if (parts) {
      chart = parts[1]!;
      chartVersion = parts[2]!;
    } else {
      chart = raw['chart'];
    }
  } else if (isRecord(raw['chart'])) {
    const metadata = isRecord(raw['chart']['metadata'])
      ? raw['chart']['metadata']
      : raw['chart'];
    chart = getString(metadata['name']);
    chartVersion = getString(metadata['version']);
  }

  return {
    name,
    namespace: getString(raw['namespace'], 'default'),
    revision: getNumber(raw['revision'], 1),
    status: getString(raw['status'], 'unknown'),
    chart,
    chartVersion,
    appVersion: getString(raw['app_version'] ?? raw['appVersion']),
    updatedAt: getString(raw['updated'] ?? raw['updatedAt']),
    values: isRecord(raw['config'])
      ? (raw['config'] as Record<string, unknown>)
      : isRecord(raw['values'])
        ? (raw['values'] as Record<string, unknown>)
        : {},
  };
}

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

/**
 * Parses a Helm release JSON or YAML file into an array of
 * {@link HelmRelease} objects.
 *
 * Handles:
 * - A single release object `{ name, namespace, chart, ... }`
 * - An array of release objects `[{ name, ... }, ...]`
 * - A YAML file containing one or more release documents
 *
 * Invalid or unrecognisable entries are silently skipped.
 *
 * @param filePath - Absolute path to the JSON/YAML file.
 * @returns Parsed releases (may be empty).
 */
export async function parseHelmReleaseFile(filePath: string): Promise<HelmRelease[]> {
  let content: string;
  try {
    content = await fsp.readFile(filePath, 'utf-8');
  } catch {
    return [];
  }

  const trimmed = content.trim();
  if (trimmed.length === 0) return [];

  // Try JSON first
  try {
    const parsed = JSON.parse(trimmed);
    if (Array.isArray(parsed)) {
      return parsed.map(parseRawRelease).filter((r): r is HelmRelease => r !== null);
    }
    const single = parseRawRelease(parsed);
    return single ? [single] : [];
  } catch {
    // Not JSON — try YAML
  }

  try {
    const docs = yaml.loadAll(trimmed);
    const results: HelmRelease[] = [];
    for (const doc of docs) {
      if (Array.isArray(doc)) {
        for (const item of doc) {
          const release = parseRawRelease(item);
          if (release) results.push(release);
        }
      } else {
        const release = parseRawRelease(doc);
        if (release) results.push(release);
      }
    }
    return results;
  } catch {
    return [];
  }
}

/**
 * Parses a raw JSON or YAML string containing Helm release data.
 *
 * @param content - Raw file content.
 * @returns Parsed releases.
 */
export function parseHelmReleaseContent(content: string): HelmRelease[] {
  const trimmed = content.trim();
  if (trimmed.length === 0) return [];

  try {
    const parsed = JSON.parse(trimmed);
    if (Array.isArray(parsed)) {
      return parsed.map(parseRawRelease).filter((r): r is HelmRelease => r !== null);
    }
    const single = parseRawRelease(parsed);
    return single ? [single] : [];
  } catch {
    // Not JSON
  }

  try {
    const docs = yaml.loadAll(trimmed);
    const results: HelmRelease[] = [];
    for (const doc of docs) {
      if (Array.isArray(doc)) {
        for (const item of doc) {
          const release = parseRawRelease(item);
          if (release) results.push(release);
        }
      } else {
        const release = parseRawRelease(doc);
        if (release) results.push(release);
      }
    }
    return results;
  } catch {
    return [];
  }
}

