                const boundaries = fileChunks.map((c) => ({
                  startLine: c.startLine,
                  endLine: c.endLine,
                }));

                const lateEmbeddings = await lateChunkEmbed(
                  embeddingClient as LateChunkEmbeddingClient,
                  fullDocument,
                  documentLines,
                  boundaries,
