// ---------------------------------------------------------------------------
// Golden Set Evaluator
// ---------------------------------------------------------------------------
//
// Scores pipeline results against golden expectations. Returns a structured
// report that can be serialised to JSON for nightly CI artifacts.

import type { Finding } from '../../src/types/index.js';
import type { ScenarioExpectation } from './expectations.js';

export interface EvalDetail {
  check: string;
  pass: boolean;
  detail: string;
}

export type EvalMode = 'heuristic' | 'ai';

export interface ScenarioEvalResult {
  scenario: string;
  displayName: string;
  pass: boolean;
  score: number;
  checks: EvalDetail[];
  topFinding: string;
  expectedPattern: string;
  confidence: number;
  evidenceCount: number;
  mode: EvalMode;
}

export interface EvalReport {
  timestamp: string;
  scenarios: Record<string, ScenarioEvalResult>;
  overallPass: boolean;
  overallScore: number;
}

function allFindingsText(findings: Finding[]): string {
  return findings
    .map((f) => [
      f.title,
      f.reasoningSummary,
      ...f.evidence.map((e) => `${e.path} ${e.note}`),
    ].join(' '))
    .join(' ');
}

function summarizeExpectedPattern(expectation: ScenarioExpectation): string {
  return expectation.topFindingMustMatch
    .map((pattern) => pattern.source)
    .join(' || ');
}

export function evaluateScenario(
  scenarioName: string,
  expectation: ScenarioExpectation,
  findings: Finding[],
  mode: EvalMode = 'heuristic',
): ScenarioEvalResult {
  const checks: EvalDetail[] = [];
  const top = findings[0];

  // 1. Minimum findings count
  checks.push({
    check: 'minFindings',
    pass: findings.length >= expectation.minFindings,
    detail: `Expected >= ${expectation.minFindings}, got ${findings.length}`,
  });

  // 2. Top finding title matches
  const topTitleMatch =
    top !== undefined &&
    expectation.topFindingMustMatch.some((re) => re.test(top.title));
  checks.push({
    check: 'topFindingTitle',
    pass: topTitleMatch,
    detail: top
      ? `Top finding: "${top.title}"`
      : 'No findings produced',
  });

  // 3. Top finding severity
  const topSeverityMatch =
    top !== undefined &&
    expectation.topFindingSeverity.includes(top.severity);
  checks.push({
    check: 'topFindingSeverity',
    pass: topSeverityMatch,
    detail: top
      ? `Got "${top.severity}", expected one of [${expectation.topFindingSeverity.join(', ')}]`
      : 'No findings',
  });

  // 4. Top finding confidence
  const topConfMatch =
    top !== undefined &&
    top.confidence >= expectation.topFindingMinConfidence;
  checks.push({
    check: 'topFindingConfidence',
    pass: topConfMatch,
    detail: top
      ? `Got ${(top.confidence * 100).toFixed(0)}%, min ${(expectation.topFindingMinConfidence * 100).toFixed(0)}%`
      : 'No findings',
  });

  // 5. Evidence citation coverage
  const allPaths = findings.flatMap((f) => f.evidence.map((e) => e.path));
  for (const pattern of expectation.mustCiteEvidence) {
    const cited = allPaths.some((p) => pattern.test(p));
    checks.push({
      check: `mustCiteEvidence: ${pattern.source}`,
      pass: cited,
      detail: cited ? 'Found matching evidence path' : `No evidence path matches /${pattern.source}/`,
    });
  }

  // 6. No hallucinations
  const fullText = allFindingsText(findings);
  for (const pattern of expectation.mustNotHallucinate) {
    const found = pattern.test(fullText);
    checks.push({
      check: `mustNotHallucinate: ${pattern.source}`,
      pass: !found,
      detail: found
        ? `HALLUCINATION DETECTED: /${pattern.source}/ found in findings text`
        : 'Clean — pattern not found',
    });
  }

  // 7. Root cause match
  const rootCauseText = top?.reasoningSummary ?? '';
  const rootCauseMatch = expectation.rootCauseMustMatch.some((re) =>
    re.test(rootCauseText),
  );
  checks.push({
    check: 'rootCauseMatch',
    pass: rootCauseMatch,
    detail: rootCauseMatch
      ? 'Root cause reasoning matches expected pattern'
      : `Root cause "${rootCauseText.slice(0, 100)}" did not match any expected pattern`,
  });

  // 8. Required identifiers
  for (const id of expectation.mustMentionIdentifiers) {
    const mentioned = fullText.toLowerCase().includes(id.toLowerCase());
    checks.push({
      check: `mustMention: ${id}`,
      pass: mentioned,
      detail: mentioned ? `Found "${id}"` : `"${id}" not found in any finding`,
    });
  }

  const passCount = checks.filter((c) => c.pass).length;
  const score = checks.length > 0 ? passCount / checks.length : 0;

  return {
    scenario: scenarioName,
    displayName: expectation.name,
    pass: checks.every((c) => c.pass),
    score,
    checks,
    topFinding: top?.title ?? 'No findings produced',
    expectedPattern: summarizeExpectedPattern(expectation),
    confidence: top?.confidence ?? 0,
    evidenceCount: findings.reduce((sum, finding) => sum + finding.evidence.length, 0),
    mode,
  };
}

export function buildEvalReport(
  results: Record<string, ScenarioEvalResult>,
): EvalReport {
  const scenarios = results;
  const allResults = Object.values(scenarios);
  const overallPass = allResults.every((r) => r.pass);
  const overallScore =
    allResults.length > 0
      ? allResults.reduce((sum, r) => sum + r.score, 0) / allResults.length
      : 0;

  return {
    timestamp: new Date().toISOString(),
    scenarios,
    overallPass,
    overallScore,
  };
}

import type { EvalReport, ScenarioEvalResult } from './evaluate.js';

function escapeMarkdownCell(value: string): string {
  return value
    .replace(/\|/g, '\\|')
    .replace(/\r?\n|\r/g, ' ')
    .trim();
}

function formatPass(pass: boolean): string {
  return pass ? 'PASS' : 'FAIL';
}

function formatPercent(value: number): string {
  return `${(value * 100).toFixed(1)}%`;
}

function formatConfidence(value: number): string {
  return value > 0 ? `${value.toFixed(2)}` : 'n/a';
}

function formatMode(mode: ScenarioEvalResult['mode']): string {
  return mode === 'ai' ? 'AI' : 'Heuristic';
}

function buildSummary(report: EvalReport) {
  const scenarioEntries = Object.entries(report.scenarios)
    .sort(([left], [right]) => left.localeCompare(right))
    .map(([scenario, result]) => ({
      scenario,
      displayName: result.displayName,
      pass: result.pass,
      score: result.score,
      topFinding: result.topFinding,
      expectedPattern: result.expectedPattern,
      confidence: result.confidence,
      evidenceCount: result.evidenceCount,
      mode: result.mode,
      checksPassed: result.checks.filter((check) => check.pass).length,
      checksTotal: result.checks.length,
    }));

  return {
    timestamp: report.timestamp,
    overallPass: report.overallPass,
    overallScore: report.overallScore,
    scenarioCount: scenarioEntries.length,
    passedScenarioCount: scenarioEntries.filter((entry) => entry.pass).length,
    failedScenarioCount: scenarioEntries.filter((entry) => !entry.pass).length,
    scenarios: scenarioEntries,
  };
}

export function generateScorecard(report: EvalReport): string {
  const summary = buildSummary(report);
  const lines: string[] = [
    '# Golden Eval Scorecard',
    '',
    `Generated: ${summary.timestamp}`,
    '',
    `Overall Pass: ${summary.overallPass ? 'YES' : 'NO'}`,
    `Overall Score: ${formatPercent(summary.overallScore)}`,
    `Scenario Count: ${summary.scenarioCount}`,
    '',
    '| Scenario | Pass/Fail | Score% | Top Finding | Expected Pattern | Confidence | Evidence Count | Heuristic/AI |',
    '| --- | --- | ---: | --- | --- | ---: | ---: | --- |',
  ];

  for (const entry of summary.scenarios) {
    lines.push(
      `| ${escapeMarkdownCell(entry.scenario)} | ${formatPass(entry.pass)} | ${formatPercent(entry.score)} | ${escapeMarkdownCell(entry.topFinding)} | ${escapeMarkdownCell(entry.expectedPattern)} | ${formatConfidence(entry.confidence)} | ${entry.evidenceCount} | ${formatMode(entry.mode)} |`,
    );
  }

  lines.push('', '## JSON Summary', '', '```json', JSON.stringify(summary, null, 2), '```');

  return lines.join('\n');
}

import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';

import { analyzeBundlePipeline, cleanupPipelineResult } from '../../../src/pipeline/analyze.js';
import type { PipelineResult } from '../../../src/pipeline/analyze.js';
import { createTestBundle, getFixturePath } from '../../helpers/create-test-bundle.js';
import { GOLDEN_EXPECTATIONS } from '../expectations.js';
import { buildEvalReport, evaluateScenario } from '../evaluate.js';
import { generateScorecard } from '../scorecard.js';

let tmpDir: string;
const results: Record<string, PipelineResult> = {};

beforeAll(async () => {
  tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'sbi-scorecard-'));

  for (const scenario of Object.keys(GOLDEN_EXPECTATIONS)) {
    const bundlePath = await createTestBundle(
      getFixturePath(scenario),
      path.join(tmpDir, `${scenario}.tar.gz`),
    );
    results[scenario] = await analyzeBundlePipeline(bundlePath, { noAi: true });
  }
});

afterAll(async () => {
  for (const result of Object.values(results)) {
    await cleanupPipelineResult(result);
  }
  fs.rmSync(tmpDir, { recursive: true, force: true });
});

describe('Golden Evaluation: scorecard', () => {
  it('generates a markdown scorecard with a machine-readable JSON summary', () => {
    const scenarioResults: Record<string, ReturnType<typeof evaluateScenario>> = {};

    for (const [scenario, expectation] of Object.entries(GOLDEN_EXPECTATIONS)) {
      scenarioResults[scenario] = evaluateScenario(scenario, expectation, results[scenario]!.findings);
    }

    const report = buildEvalReport(scenarioResults);
    const scorecard = generateScorecard(report);

    expect(scorecard).toContain('# Golden Eval Scorecard');
    expect(scorecard).toContain(
      '| Scenario | Pass/Fail | Score% | Top Finding | Expected Pattern | Confidence | Evidence Count | Heuristic/AI |',
    );
    expect(scorecard).toContain('| --- | --- | ---: | --- | --- | ---: | ---: | --- |');
    expect(scorecard).toContain('## JSON Summary');
    expect(scorecard).not.toContain('undefined');

    for (const scenario of Object.keys(GOLDEN_EXPECTATIONS)) {
      expect(scorecard).toContain(`| ${scenario} |`);
    }

    const jsonBlockMatch = scorecard.match(/```json\n([\s\S]+?)\n```/);
    expect(jsonBlockMatch).not.toBeNull();

    const summary = JSON.parse(jsonBlockMatch![1]!) as {
      overallScore: number;
      scenarioCount: number;
      scenarios: Array<{ scenario: string }>;
    };

    expect(summary.scenarioCount).toBe(Object.keys(GOLDEN_EXPECTATIONS).length);
    expect(summary.scenarios).toHaveLength(Object.keys(GOLDEN_EXPECTATIONS).length);
    expect(summary.overallScore).toBeGreaterThan(0.9);
  });
});

